const students = [{ id: 1, name: '林同学' }, { id: 2, name: '周同学' }];
const submissions = [{ studentId: 1, score: 92 }, { studentId: 2, score: 85 }];

const rows = submissions.map(submission => ({
  name: students.find(student => student.id === submission.studentId).name,
  score: submission.score,
}));

console.log(JSON.stringify(rows, null, 2));
